NEW_FILES = {}
CHANGELOG = '## [0.236.0] - the scout window focuses a floor, tilts, spins on, and turns itself\n\n**The factory\'s roadmap 295, the walker trying it in a walk copy:** "the up and down isn\'t working? also is there a\nway to prioritize the view to focus on where you are as you rotate it so there isn\'t corners that just stay covered\nas you rotate it?" -- and asked for vertical tilt, a turn that keeps spinning after the drag lets go, a slow automatic\nturn, and "scroll wheel should be the up down as well (floors)".\n\n### Fixed\n- **Up and down did nothing you could see**: the storeys started fully spread, so up was already at its end and each\n  step down moved them 1.5 m. And the walk copy\'s player polls the arrow keys for itself and recaptures the mouse on\n  any click, so it walked and grabbed the drag while the window had them: the F6 caller now holds the player while\n  the window is open and gives it back on the window\'s own `closed` -- cancel closes it too.\n\n### Added\n- **A floor in focus** (`focus(i)`, `focused()`): up and down -- and the scroll wheel, a notch a floor -- step it\n  through the building, the whole of it, then the top floor and each one below, and past the top the whole building\n  again. The floors above it step aside, hidden with their points; the ones below dim; the view centres on it and\n  frames it, so turning shows every side of it with nothing standing over it.\n- **Tilt** (`tilt(degrees)`): a drag up and down raises the view towards overhead or lowers it towards level,\n  12-80 degrees.\n- **A flick spins on**, dying away; **left alone** for 3 s it turns itself at 10 degrees a second (`auto_turn`).\n\n### Tests\n- `test_scout_window.py`: the seam carries `tilt`, `focus` and `focused`; up and down step the focus, not the spread;\n  the floors above are hidden and the ones below dimmed; a drag turns, tilts and leaves a spin; it turns itself when\n  left alone; the walk copy holds its player while the window is open. On 0.235.0 all three fail on behaviour, each\n  an assertion: the seam lacks `tilt`, the overlay holds nothing, up and down still move the spread.\n\n'
OLD_VERSION, NEW_VERSION = '0.235.0', '0.236.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
